// ---- live values ----
const fcVal = (id) => { if (!id) return null; return C.fcAttr ? num(attr(id, C.fcAttr)) : num(st(id)); };
const L = {
  fcNow: fcVal(C.fcNow),
  fc30: fcVal(C.fc30),
  fcMedian: num(st(C.fcNow)),
  irr: (C.useIrr && C.irr) ? num(st(C.irr)) : null,
  pv: pw(C.pv),
  grid: pw(C.grid),
  evConn: /^(binary_sensor|switch|input_boolean)\./.test(C.evConn) ? on(C.evConn) : (!!C.evConn && !BAD.includes(st(C.evConn)) && !C.offVals.includes(low(st(C.evConn)))),
  evPow: pw(C.evPow),
  evGreen: C.evGreen ? num(st(C.evGreen)) : null,
  mode: st(C.mode),
  solarSwOn: !C.solarSw || on(C.solarSw),
  hpvcOn: on(C.hpvcEn),
  hpvcLimited: on(C.hpvcLim),
  sun: st('sun.sun') === 'above_horizon',
  owns: on('input_boolean.hesc_owns_hpvc_off'),
  hpvcStatus: txt(C.hpvcStatus),
  negMode: on('binary_sensor.hpvc_negative_price_mode'),
  negFault: on('input_boolean.hpvc_negative_override_fault'),
  autoResume: on('input_boolean.hpvc_auto_resume_pending'),
  allIn: C.allIn ? num(st(C.allIn)) : null,
  evSoc: C.evSoc ? num(st(C.evSoc)) : null,
  relIface: !!S['input_boolean.hpvc_external_release_request'],
  relReq: on('input_boolean.hpvc_external_release_request'),
  relActive: on('binary_sensor.hpvc_external_release_active'),
};
const missing = [];
if (L.fcNow === null) missing.push('forecast now');
if (L.fc30 === null) missing.push('forecast +30m');
if (L.pv === null) missing.push('PV power');
if (L.evPow === null) missing.push('EV power');
if (!C.evConn || BAD.includes(st(C.evConn))) missing.push('EV connected');
if (!C.mode || BAD.includes(L.mode)) missing.push('charger mode');
if (!C.standalone && BAD.includes(st(C.hpvcEn))) missing.push('HPVC enabled');
const irrUsed = C.useIrr && !!C.irr && L.irr !== null;
// charger in its solar mode: mode value in the configured list (comma separated), plus the optional solar switch
const inSolar = C.ecoVals.includes(low(L.mode)) && L.solarSwOn;
const valid = missing.length === 0;

// ---- persistent runtime context ----
const today = new Date(now).toLocaleDateString('sv-SE', { timeZone: 'Europe/Amsterdam' });
let X = flow.get('hesc') || { state: 'IDLE', since: now, stableSince: null, dipSince: null, stopSince: null,
  cooldownUntil: 0, lastTick: now, rel: null, eco: null, acc: null, day: null, last: {} };
if (!X.day || X.day.date !== today) X.day = { date: today, releases: 0, success: 0, failed: 0, ecoSessions: 0, fcWh: 0, pvWh: 0, evWh: 0, greenKwh: 0 };
const dtH = Math.min(Math.max((now - (X.lastTick || now)) / 3600000, 0), 0.05); // cap 3 min
X.lastTick = now;

const evWaiting = L.evConn && inSolar && L.evPow !== null && L.evPow <= C.activeW;
const evCharging = L.evPow !== null && L.evPow > C.activeW;
const hpvcBlocks = L.hpvcOn && L.hpvcLimited;
// v0.5.1 plan B (25-09-2026): take over from HPVC only in a normal HPVC control state —
// not at negative price, Night Restore, HBC Charge Priority (battery first), faults or auto-resume.
// v0.5.2: optional EV battery level — explanation only, never used for control
const evFull = L.evSoc !== null && L.evSoc >= C.evFullSoc - 1;
const HPVC_NORMAL = ['PV dynamically adjusted', 'Monitoring low price', 'PV full / price OK', 'PV restored', 'PV minimum limit'];
const hpvcSafe = HPVC_NORMAL.includes(L.hpvcStatus) && !L.negMode && !L.negFault && !L.autoResume && !(L.allIn !== null && L.allIn <= 0);
// HPVC stops writing when disabled and leaves limits as they are, so HESC sets the HPVC inverters to full itself.
const INV = [];
let invOk = C.invCount > 0;
for (let s = 1; s <= C.invCount; s++) {
  const ent = low(txt('input_text.hpvc_pv' + s + '_limit_number'));
  const method = txt('input_select.hpvc_pv' + s + '_control_method');
  const unit = low(txt('input_select.hpvc_pv' + s + '_limit_unit'));
  const full = num(st('input_number.hpvc_pv' + s + '_full_limit'));
  if (method !== 'Number entity' || !/^number\./.test(ent) || !(full > 0) || (unit !== 'watts' && unit !== 'percent')) { invOk = false; continue; }
  const mx = num(attr(ent, 'max'));
  let target = unit === 'percent' ? 100 : full;
  if (mx !== null) target = Math.min(target, mx);
  const cur = num(st(ent));
  INV.push({ ent: ent, target: target, below: cur === null || cur < target - 1 });
}
function releasePv(force) { if (C.shadow) return 0; let n = 0; for (const i of INV) if (force || i.below) { msgs2.push(act('number.set_value', i.ent, { value: i.target })); n++; } return n; }
const fcLow = (L.fcNow !== null && L.fc30 !== null) ? Math.min(L.fcNow, L.fc30) : null;
const fcStartOk = fcLow !== null && fcLow >= C.pStart;
const fcHoldOk = fcLow !== null && fcLow >= C.pHold;
const irrStartOk = !irrUsed || L.irr >= C.irrStart;
const irrHoldOk = !irrUsed || L.irr >= C.irrHold;

const msgs1 = [], msgs2 = [], msgs3 = [], msgs4 = [];
const act = (action, entity, data) => ({ payload: { action: action, target: { entity_id: [entity] }, data: data || {} } });
const hist = (o) => msgs4.push({ payload: JSON.stringify(Object.assign({ ts: new Date(now).toISOString(), shadow: C.shadow }, o)) });
const r0 = (v) => v === null || v === undefined ? null : Math.round(v);
const REQ = 'input_boolean.hpvc_external_release_request';

function snapshot() {
  return { fc_now: r0(L.fcNow), fc_30m: r0(L.fc30), fc_median: r0(L.fcMedian), irr: r0(L.irr), pv: r0(L.pv), grid: r0(L.grid), ev: r0(L.evPow), mode: L.mode, hpvc_on: L.hpvcOn, hpvc_limited: L.hpvcLimited, hpvc_status: L.hpvcStatus, standalone: !!C.standalone, ev_soc: L.evSoc === null ? null : Math.round(L.evSoc * 10) / 10 };
}
function integrate(sess) {
  if (!sess) return;
  if (L.fcMedian !== null) sess.fcWh += L.fcMedian * dtH;
  if (L.pv !== null) sess.pvWh += L.pv * dtH;
  if (L.evPow !== null) sess.evWh += L.evPow * dtH;
}
function closeSession(sess, type, reason) {
  const green = (sess.greenStart !== null && L.evGreen !== null) ? Math.max(0, L.evGreen - sess.greenStart) : null;
  const acc = sess.fcWh > 0 ? Math.round(100 * sess.pvWh / sess.fcWh) : null;
  hist({ type: type, reason: reason, start: new Date(sess.start).toISOString(), minutes: Math.round((now - sess.start) / 60000),
    forecast_wh: Math.round(sess.fcWh), pv_wh: Math.round(sess.pvWh), actual_vs_forecast_pct: acc, ev_wh: Math.round(sess.evWh),
    ev_green_kwh: green === null ? null : Math.round(green * 100) / 100, ev_started: !!sess.evStarted, start_delay_min: sess.startDelayMin === undefined ? null : sess.startDelayMin, forced_start: sess.forced === undefined ? undefined : !!sess.forced, start_ctx: sess.ctx, end_ctx: snapshot() });
  if (!sess.forced) { X.day.fcWh += sess.fcWh; X.day.pvWh += sess.pvWh; X.day.evWh += sess.evWh; if (green !== null) X.day.greenKwh += green; }
}
function newSession() { return { start: now, fcWh: 0, pvWh: 0, evWh: 0, greenStart: L.evGreen, evStarted: false, ctx: snapshot() }; }

let reason = '';
function restore(why) {
  if (!C.legacy) { if (!C.shadow && L.relReq) msgs2.push(act('input_boolean.turn_off', REQ)); } else if (!C.shadow && L.owns) { msgs2.push(act('input_boolean.turn_on', C.hpvcEn)); msgs3.push(act('input_boolean.turn_off', 'input_boolean.hesc_owns_hpvc_off')); }
  if (X.rel) { if (X.rel.evStarted) X.day.success++; else if (why !== 'EV full') X.day.failed++; closeSession(X.rel, 'release', why); X.rel = null; }
  X.cooldownUntil = now + C.cooldown;
  X.state = 'IDLE'; X.since = now; X.stableSince = null; X.dipSince = null; X.stopSince = null;
  reason = (C.legacy ? 'Restored HPVC: ' : 'Release ended: ') + why;
}

// ---- manual intervention / disable while owning ----
if (!C.shadow && L.owns && (X.state === 'WAIT_START' || X.state === 'CHARGING') && L.hpvcOn && X.rel && now - X.rel.start > 90000) {
  msgs3.push(act('input_boolean.turn_off', 'input_boolean.hesc_owns_hpvc_off'));
  if (X.rel) { closeSession(X.rel, 'release', 'manual_hpvc_on'); X.rel = null; }
  X.state = 'IDLE'; X.since = now; reason = 'HPVC switched on manually — release abandoned';
}
if (!C.enabled && X.state !== 'IDLE') restore('HESC disabled');
else if (C.standalone && X.state !== 'IDLE') restore('standalone mode switched on');

// ---- plan B safety while HESC owns HPVC-off (v0.5.1) ----
if (C.legacy && X.state !== 'IDLE' && L.allIn !== null && L.allIn <= 0) restore('all-in price at or below zero');
else if (X.state !== 'IDLE' && L.owns && !L.hpvcOn) releasePv(false);
// v0.6.0: a request left on while idle (e.g. after a Node-RED restart) is withdrawn
if (!C.legacy && !C.shadow && X.state === 'IDLE' && L.relReq) msgs2.push(act('input_boolean.turn_off', REQ));

// ---- state machine ----
if (C.enabled && reason === '') {
  if (X.state === 'IDLE') {
    const attemptsLeft = (X.day.releases - X.day.success) < C.maxAttempts;
    const ready = !C.standalone && valid && L.sun && evWaiting && hpvcBlocks && (C.legacy ? (hpvcSafe && invOk) : L.relIface) && !evFull && fcStartOk && irrStartOk && now >= X.cooldownUntil && attemptsLeft;
    if (ready) {
      X.stableSince = X.stableSince || now;
      if (now - X.stableSince >= C.tStable) {
        if (!C.legacy) {
          X.state = 'WAIT_ACK'; X.since = now; X.stableSince = null;
          if (!C.shadow) msgs2.push(act('input_boolean.turn_on', REQ));
          reason = 'Release requested: HESC ' + (C.shadow ? 'would ask' : 'asked') + ' HPVC for full PV, waiting for HPVC to confirm';
        } else {
        X.state = 'WAIT_START'; X.since = now; X.stableSince = null; X.day.releases++;
        X.rel = newSession();
        if (!C.shadow) { msgs2.push(act('input_boolean.turn_off', C.hpvcEn)); msgs3.push(act('input_boolean.turn_on', 'input_boolean.hesc_owns_hpvc_off')); }
      if (!C.shadow) releasePv(true);
        reason = 'Release: HPVC ' + (C.shadow ? 'would be' : 'is') + ' switched off so the charger can start in solar mode';
        }
