  '.bar{display:flex;align-items:center;gap:8px;margin:4px 0}.bl{width:80px;text-align:right;color:var(--mut);font-size:12px}.bt{flex:1;height:12px;background:var(--ln);border-radius:4px;overflow:hidden}.bf{display:block;height:12px;background:var(--ac)}.bv{width:30px;font-size:12px}';

// ---- Report layout in the same structure as the HPVC report ----
const css2 = ':root{color-scheme:dark;--bg:#0a121a;--card:#15222e;--tx:#f2f5f8;--mut:#93a3af;--ln:#2a3a48;--ac:#18b9df;--ok:#54d36b;--wr:#f3c44f;--bad:#ef5350}' +
  'body{background:radial-gradient(circle at 50% 0,#13212f,#0a121a 60%) fixed;color:var(--tx)}' +
  '.wrap{max-width:1220px;padding:28px}' +
  '.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.top h1{margin:0;font-size:27px}.meta{color:var(--mut);margin-top:4px}' +
  '.dl{border:0;border-radius:10px;background:var(--ac);color:#fff;font-weight:800;padding:12px 17px;cursor:pointer;font-size:14px}' +
  'nav{display:flex;flex-wrap:wrap;gap:8px;margin:22px 0 26px}nav a{color:var(--tx);text-decoration:none;background:#152633;border:1px solid var(--ln);border-radius:999px;padding:7px 12px}nav a:hover{border-color:var(--ac)}' +
  'section{margin:0 0 26px;scroll-margin-top:12px}h2{font-size:17px;margin:0 0 10px}' +
  '.box,.kpi,.panel{background:linear-gradient(180deg,#172836,#111e29);border:1px solid var(--ln);border-radius:12px}' +
  '.panel{overflow:hidden}.kvr{display:flex;justify-content:space-between;gap:16px;padding:12px 16px;border-top:1px solid var(--ln)}.kvr:first-child{border-top:0}.kvr span{color:var(--mut)}.kvr b{text-align:right}' +
  '.kb{font-size:22px}.lead{color:var(--mut);font-style:italic;font-size:13px;margin-top:4px}' +
  'details.compact{background:linear-gradient(180deg,#172836,#111e29);border:1px solid var(--ln);border-radius:12px;padding:0}details.compact>summary{cursor:pointer;padding:12px 16px;font-weight:700;list-style:none}details.compact>summary::before{content:"\\25B8  ";color:var(--ac)}details.compact[open]>summary::before{content:"\\25BE  "}details.compact>.box{border:0;border-top:1px solid var(--ln);border-radius:0;margin:0;background:none}' +
  '#live .kpis{grid-template-columns:repeat(auto-fit,minmax(150px,1fr))}' +
  '#settings td{padding:10px 14px}#settings td:first-child{color:var(--mut)}#settings td:last-child{text-align:right;font-weight:700}#settings code{font:inherit}' +
  '@media (max-width:640px){.wrap{padding:16px}.top{flex-direction:column}}';

const kv = (pairs) => '<div class="panel">' + pairs.map((p) => '<div class="kvr"><span>' + p[0] + '</span><b>' + p[1] + '</b></div>').join('') + '</div>';
const countRows = (html) => ((html || '').match(/<tr/g) || []).length;
const nOr = (v) => { const x = Number(v); return Number.isFinite(x) ? Math.round(x) : null; };

// Executive summary
const hpvcOn = liveVal(src('hesc_hpvc_enabled_entity'));
const hpvcLim = liveVal(src('hesc_hpvc_limited_entity'));
const summary = kv([
  ['HESC status', st('input_boolean.hesc_enabled') === 'off' ? 'Disabled' : 'Enabled'],
  ['Configuration', issues.length ? '<span style="color:var(--wr)">Attention: ' + esc(issues.join(', ')) + '</span>' : 'Valid'],
  ['Mode', shadow ? 'Shadow — evaluates only' : 'Live — asks HPVC for releases'],
  ['Current state', esc(st('input_text.hesc_state') || '–')],
  ['Reason', esc(st('input_text.hesc_reason') || '–')],
  ['Status since', esc(RT && RT.since ? fmtT(new Date(RT.since).toISOString()) : '–')],
  ['Last action', (function () { const v = st('input_text.hesc_last_action'); return (!v || v === 'unknown' || v === 'unavailable') ? 'None yet' : esc(v); })()],
  ['HPVC', (hpvcOn === 'on' ? 'On' : hpvcOn === 'off' ? 'Off' : esc(hpvcOn)) + ' · ' + (hpvcLim === 'on' ? 'limiting PV' : 'not limiting')],
  ['Today so far', todayText(RT && RT.day)],
  ['Runtime evaluation', esc(now.toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam' }))]
]);

// Live status cards
const w = (v) => { const x = nOr(v); return x === null ? '–' : x + ' W'; };
const gridV = nOr(liveVal(src('hesc_grid_power_sensor')));
const irrId = src('hesc_irradiance_sensor');
const liveCards =
  card('FORECAST NOW', w(liveVal(src('hesc_forecast_now_sensor'), fcAttr)), 'Cautious estimate' + (fcAttr ? ' (' + esc(fcAttr) + ')' : '')) +
  card('FORECAST +30 MIN', w(liveVal(src('hesc_forecast_30m_sensor'), fcAttr)), 'Start threshold ' + w(st('input_number.hesc_p_start'))) +
  card('PV', w(liveVal(src('hesc_pv_power_sensor'))), 'Current solar power') +
  card('GRID', gridV === null ? '–' : Math.abs(gridV) + ' W ' + (gridV < 0 ? 'export' : 'import'), 'Grid meter') +
  card('EV CHARGING', w(liveVal(src('hesc_ev_power_sensor'))), 'EV ' + (liveVal(src('hesc_ev_connected_sensor')) === 'on' ? 'connected' : 'not connected') + ' · charger ' + esc(liveVal(src('hesc_charger_mode_entity')))) +
  (irrId ? card('IRRADIANCE', (nOr(liveVal(irrId)) === null ? '–' : nOr(liveVal(irrId)) + ' W/m²'), 'Weather station') : '');

const nSess = countRows(sessRows), nEv = countRows(evRows);
const navItems = [['summary', 'Status'], ['live', 'Live'], ['advice', 'Advice'], ['accuracy', 'Accuracy'], ['sources', 'Sources'], ['days', 'Days'], ['sessions', 'Sessions'], ['events', 'Events'], ['settings', 'Settings'], ['runtime', 'Runtime']];
const stamp = now.toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam' });

let out = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HESC report</title><style>' + css + css2 + '</style></head><body><div class="wrap">' +
  '<header class="top"><div><h1>HESC report</h1><div class="meta">' + esc(stamp) + ' · ' + VERSION + ' · history since ' + esc(first ? fmtT(first) : '–') + ' · ' + rows.length + ' records</div></div><button class="dl" id="download">Download report</button></header>' +
  '<nav>' + navItems.map((n) => '<a href="#' + n[0] + '">' + n[1] + '</a>').join('') + '</nav>' +
  '<section id="summary"><h2>Executive Summary</h2>' + summary + '</section>' +
  '<section id="live"><h2>Live Status</h2><div class="kpis">' + liveCards + '</div></section>' +
  '<section id="advice">' + (advHtml || '<h2>Advice</h2><div class="sub">No advice available yet.</div>') + '</section>' +
  '<section id="accuracy"><h2>How well did the forecast match reality during solar charging?</h2><div class="kpis">' + kpis + '</div>' +
  '<div class="box"><div class="sub" style="margin-bottom:6px">Actual PV as % of the Solcast forecast (median estimate), per solar session of 10 min or longer</div>' + (accList.length ? distRows : '<span class="mut">No solar sessions recorded yet.</span>') + '</div></section>' +
  '<section id="sources"><h2>How reliable are the sources?</h2><div class="sub">All daylight 15-minute intervals, also without charging. Intervals in which HPVC limited PV are left out, because curtailed PV says nothing about the forecast.</div><div class="kpis">' + relKpis + '</div>' +
  '<div class="box"><table><tr><th>Day</th><th>Trend</th><th>Intervals</th><th>Actual / forecast</th><th>Within ±20%</th><th>Actual ≥ cautious</th><th>PV per kW/m²</th><th>Irradiance ↔ PV</th></tr>' + (relRows || '<tr><td colspan="8" class="mut">No intervals recorded yet.</td></tr>') + '</table><div class="sub" style="margin-top:6px">Trend: ↑ better means the forecast was closer to 100% than the previous day. PV per kW/m² and the correlation show how well the weather station explains the PV output (1,0 = perfect).</div></div></section>' +
  '<section id="days"><h2>Per day (newest first)</h2><div class="box"><table><tr><th>Day</th><th>Trend</th><th>Solar sessions</th><th>Forecast kWh</th><th>Actual PV kWh</th><th>Actual / forecast</th><th>EV kWh</th><th>EV solar kWh</th><th>Releases ok</th></tr>' + (dayRows || '<tr><td colspan="9" class="mut">No data yet.</td></tr>') + '</table><div class="sub" style="margin-top:6px">Trend compares actual/forecast with the previous day: ↑ higher, ↓ lower, → within 5 points.</div></div></section>' +
  '<section id="sessions"><details class="compact"><summary>Sessions · ' + nSess + ' entries (newest first)</summary><div class="box"><table><tr><th>Start</th><th>Type</th><th>Min</th><th>Forecast kWh</th><th>Actual PV kWh</th><th>Actual / forecast</th><th>EV kWh</th><th>EV solar kWh</th><th>EV started</th><th>Reason</th></tr>' + (sessRows || '<tr><td colspan="10" class="mut">No sessions yet.</td></tr>') + '</table></div></details></section>' +
  '<section id="events"><details class="compact"><summary>Decisions and events · ' + nEv + ' entries (newest first)</summary><div class="box"><table><tr><th>Time</th><th>Event</th><th>Forecast</th><th>Irradiance</th><th>PV</th></tr>' + (evRows || '<tr><td colspan="5" class="mut">No events yet.</td></tr>') + '</table></div></details></section>' +
  '<section id="settings"><h2>Settings</h2><div class="box"><table>' + setRows.replace(/<td>HESC (\w)/g, (m, c) => '<td>' + c.toUpperCase()) + '</table></div><h2 style="margin-top:18px">Input check</h2><div class="box"><table>' + liveRows + '</table></div></section>' +
  '<section id="runtime"><h2>Runtime</h2>' + kv([
    ['Engine state', esc(RT && RT.state || '–') + ' since ' + esc(RT && RT.since ? fmtT(new Date(RT.since).toISOString()) : '–')],
    ['Cooldown until', esc(RT && RT.cooldownUntil && RT.cooldownUntil > Date.now() ? fmtT(new Date(RT.cooldownUntil).toISOString()) : 'none')],
    ['History file', '<code>/homeassistant/hesc-data/history.jsonl</code> · ' + rows.length + ' records · ' + Math.round(raw.length / 1024) + ' KiB']
  ]) + '</section>' +
  '<div class="sub" style="margin:20px 0">Home EV Solar Control works alongside Home PV Control (HPVC). The only thing it ever switches is the HPVC on/off switch, and only when shadow mode is off. In shadow mode it evaluates and logs, but switches nothing.</div></div>' +
  '<script>document.getElementById("download").addEventListener("click",function(){var b=new Blob(["<!doctype html>"+document.documentElement.outerHTML],{type:"text/html;charset=utf-8"});var a=document.createElement("a");a.href=URL.createObjectURL(b);a.download="hesc-report-' + new Date().toISOString().slice(0, 16).replace(/[:T]/g, '-') + '.html";a.click();setTimeout(function(){URL.revokeObjectURL(a.href)},1000)});' +
  'fetch("/api/webhook/hesc_report_viewed",{method:"POST",keepalive:true}).catch(function(){});</script></body></html>';

msg.payload = out;
msg.filename = '/homeassistant/www/hesc/report.html';
node.status({ fill: 'green', shape: 'dot', text: 'report ' + rows.length + ' records · ' + now.toLocaleTimeString('nl-NL', { timeZone: 'Europe/Amsterdam' }) });
// Small launcher page: /local files are cached by the browser for a month, so the dashboard
// opens open.html, which loads report.html with a unique query string (always the newest report).
const openMsg = { hescOpen: true, filename: '/homeassistant/www/hesc/open.html', payload: "<!doctype html><html><head><meta charset=\"utf-8\"><title>HESC report</title><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"></head><body style=\"background:#0a121a;color:#ccc;font-family:sans-serif\">Opening HESC report…<script>location.replace(\"report.html?t=\"+Date.now());</script></body></html>" };
return [[openMsg, msg]];

// The launcher page (open.html) passes this node too; only the report itself marks ready.
if (msg.hescOpen) return null;
// Report written: mark ready and store the generation time.
flow.set('hescReportBusy', 0);
const t = new Date().toLocaleString('nl-NL', { timeZone: 'Europe/Amsterdam' });
node.status({ fill: 'green', shape: 'dot', text: 'ready ' + t });
return [[
  { payload: { action: 'input_boolean.turn_on', target: { entity_id: ['input_boolean.hesc_report_ready'] }, data: {} } },
  { payload: { action: 'input_text.set_value', target: { entity_id: ['input_text.hesc_report_generated'] }, data: { value: t } } }
]];

// HESC — Advisor (v1.2.0). Turns the recent history into plain-language setting advice.
// v1.2.0: the start threshold advice looks at ALL solar sessions (short ones too), only at sessions from the current
// way of working (standalone or with HPVC), and only once enough different days are collected (MINDAYS).
// Advice only: it never changes a setting. Runs daily and before every report.
// Input: msg.payload = contents of history.jsonl ('' if missing), msg.topic 'advice' for the daily run.
// out1: the same msg (+ msg.advice) to the report builder (report path only)
// out2: HA actions (input_text.hesc_advice / hesc_advice_updated), only on change
const S = global.get('homeassistant.homeAssistant.states') || {};
const st = (id) => S[id] ? S[id].state : undefined;
const num = (id, d) => { const v = parseFloat(st(id)); return isNaN(v) ? d : v; };
const now = Date.now();
const WINDOW = Math.max(7, num('input_number.hesc_advice_window_days', 30));
const MINRUNS = Math.max(3, num('input_number.hesc_advice_min_runs', 8));
const LASTING = 20; // an Eco session counts as "lasting" from 20 minutes
const MINDAYS = 7; // advice on the start threshold only after sessions on this many different days
const TARGET = 0.6; // a start threshold is good when at least 60% of the sessions it lets start keep charging 20 min
const cur = { pStart: num('input_number.hesc_p_start', 2000), pHold: num('input_number.hesc_p_hold', 1500), tStart: num('input_number.hesc_t_start', 10),
  irrStart: num('input_number.hesc_irr_start', 220), irrHold: num('input_number.hesc_irr_hold', 160) };
const useIrr = st('input_boolean.hesc_use_irradiance') === 'on' && !!st('input_text.hesc_irradiance_sensor') && !['unknown', 'unavailable', ''].includes(st('input_text.hesc_irradiance_sensor'));
const since = now - WINDOW * 86400000;
const qn = (a, p) => { const s = a.filter(x => typeof x === 'number' && isFinite(x)).sort((x, y) => x - y); if (!s.length) return null; return s[Math.min(s.length - 1, Math.max(0, Math.round(p * (s.length - 1))))]; };
const r100 = (v) => Math.round(v / 100) * 100;
const fmtW = (v) => Math.round(v).toLocaleString('en-US') + ' W';

// ---- parse (only the window: the advice follows the season) ----
const rows = [];
for (const line of String(msg.payload || '').split('\n')) { if (!line.trim()) continue; try { const r = JSON.parse(line); const t = Date.parse(r.start || r.slot_start || r.ts); if (t >= since) rows.push(r); } catch (e) { /* skip */ } }
// A solar-mode session that starts while there is hardly any sun (forecast AND PV below the hold threshold)
// was started by hand or by a schedule. It is logged, but left out of the advice and the accuracy figures.
// Works for every charger: it only looks at forecast and PV, not at charger-specific states.
const isForced = (r) => r.forced_start === true || (r.forced_start === undefined && r.start_ctx && typeof r.start_ctx.fc_now === 'number' && typeof r.start_ctx.pv === 'number' && r.start_ctx.fc_now < cur.pHold && r.start_ctx.pv < cur.pHold);
const eco = rows.filter(r => r.type === 'eco_charge' && !isForced(r));
const lasting = eco.filter(r => r.minutes >= LASTING && r.start_ctx && typeof r.start_ctx.fc_now === 'number');
const live = rows.filter(r => r.type === 'release' && !r.shadow && r.reason !== 'EV full'); // v0.5.2: a release that ends because the EV is full is not a failed release
const liveOk = live.filter(r => r.ev_started);
const accRows = rows.filter(r => r.type === 'accuracy' && (r.hpvc_limited_share || 0) < 0.1 && r.fc_w > 50);

const items = [];
let summary = '';

// 1. start / hold threshold — from ALL solar sessions of the current way of working (v1.2.0).
// Sessions only start above the current threshold, so the Advisor can advise to raise it (too many short sessions),
// and shows the trade-off: short sessions avoided versus good sessions lost.
const standaloneNow = st('input_boolean.hesc_standalone') === 'on';
const modeOf = (r) => (r.start_ctx && typeof r.start_ctx.standalone === 'boolean') ? r.start_ctx.standalone : !(r.start_ctx && r.start_ctx.hpvc_on);
const modeLabel = standaloneNow ? 'standalone' : 'with HPVC';
const modeRows = eco.filter(r => r.start_ctx && typeof r.start_ctx.fc_now === 'number' && modeOf(r) === standaloneNow);
const dayKey = (r) => new Date(Date.parse(r.start || r.ts)).toLocaleDateString('nl-NL', { timeZone: 'Europe/Amsterdam' });
const nDays = new Set(modeRows.map(dayKey)).size;
const pushThreshold = (p, measured, basis) => {
  const h = r100(p * 0.8);
  const same = Math.abs(p - cur.pStart) < 200;
  items.push({ key: 'p_start', title: 'Start and hold threshold', status: same ? 'ok' : 'advice', basis: basis, measured: measured,
    advice: same ? 'Keep the start threshold at ' + fmtW(cur.pStart) + '.' : 'Set the start threshold to ' + fmtW(p) + ' and the hold threshold to ' + fmtW(h) + ' (now ' + fmtW(cur.pStart) + ' / ' + fmtW(cur.pHold) + ').',
    value: { p_start: p, p_hold: h } });
  return same;
};
if (modeRows.length >= MINRUNS && nDays >= MINDAYS) {
  const at = (p) => { const a = modeRows.filter(r => r.start_ctx.fc_now >= p); const l = a.filter(r => r.minutes >= LASTING).length; return { n: a.length, l: l, share: a.length ? l / a.length : 0 }; };
  const now0 = at(cur.pStart);
  let p = cur.pStart;
  if (now0.n && now0.share < 0.5) {
    const cands = [...new Set(modeRows.map(r => r100(r.start_ctx.fc_now)))].filter(v => v > cur.pStart).sort((x, y) => x - y);
    for (const c of cands) { const x = at(c); if (x.n >= 3 && x.share >= TARGET) { p = Math.min(8000, c); break; } }
  }
  const lostGood = modeRows.filter(r => r.minutes >= LASTING && r.start_ctx.fc_now < p).length;
  const avoidedShort = modeRows.filter(r => r.minutes < LASTING && r.start_ctx.fc_now < p).length;
  const same = pushThreshold(p, modeRows.length + ' solar sessions on ' + nDays + ' days (' + modeLabel + '). ' + now0.l + ' of ' + now0.n +
    ' kept charging for ' + LASTING + ' minutes or more.' + (p !== cur.pStart ? ' At ' + fmtW(p) + ', ' + avoidedShort + ' short sessions would not have started, but also ' + lostGood + ' good ones.' : ''), 'sessions');
  summary = (same ? 'Start threshold fits (' + fmtW(cur.pStart) + ')' : 'Start ' + fmtW(p) + ' (now ' + fmtW(cur.pStart) + ')') + ': ' + now0.l + ' of ' + now0.n + ' sessions kept charging';
} else {
  items.push({ key: 'p_start', title: 'Start and hold threshold', status: 'waiting',
    measured: (modeRows.length >= MINRUNS ? modeRows.length + ' solar sessions (enough)' : modeRows.length + ' of ' + MINRUNS + ' solar sessions') + ', on ' + nDays + ' of ' + MINDAYS + ' days (' + modeLabel + ').', advice: 'No advice yet. HESC learns from the solar sessions of the way you work now; advice appears once enough of them, on enough different days, are collected.' });
  summary = 'Collecting data: ' + (modeRows.length >= MINRUNS ? modeRows.length + ' solar sessions' : modeRows.length + ' of ' + MINRUNS + ' solar sessions') + ', ' + nDays + ' of ' + MINDAYS + ' days';
}

// 2. wait for the charger — only real (non-shadow) releases show the charger's start delay
const delays = liveOk.map(r => r.start_delay_min).filter(v => typeof v === 'number');
if (delays.length >= Math.max(3, Math.round(MINRUNS / 2))) {
  const t = Math.min(30, Math.max(3, Math.ceil(qn(delays, 0.9)) + 2));
  const same = Math.abs(t - cur.tStart) <= 1;
  items.push({ key: 't_start', title: 'Wait for the charger to start', status: same ? 'ok' : 'advice',
    measured: 'After ' + delays.length + ' releases the charger started within ' + Math.ceil(qn(delays, 0.9)) + ' minutes in 9 of 10 cases.',
    advice: same ? 'Keep ' + cur.tStart + ' minutes.' : 'Set the wait time to ' + t + ' minutes (now ' + cur.tStart + ').', value: { t_start: t } });
} else {
  items.push({ key: 't_start', title: 'Wait for the charger to start', status: 'waiting',
    measured: live.length ? delays.length + ' releases with a measured start so far.' : 'Only measurable with shadow mode off (real releases).', advice: 'No advice yet.' });
}

// 3. failed real releases — the start threshold is too low if many releases do not lead to charging
if (live.length >= Math.max(3, Math.round(MINRUNS / 2))) {
  const share = liveOk.length / live.length;
  if (share < 0.5) items.push({ key: 'fails', title: 'Releases without charging', status: 'advice',
    measured: 'Only ' + liveOk.length + ' of ' + live.length + ' releases led to charging.', advice: 'Raise the start threshold to ' + fmtW(r100(cur.pStart * 1.15)) + '.', value: { p_start: r100(cur.pStart * 1.15) } });
  else items.push({ key: 'fails', title: 'Releases without charging', status: 'ok',
    measured: liveOk.length + ' of ' + live.length + ' releases led to charging.', advice: 'No change needed.' });
}

// 4. forecast reliability (all daylight intervals, not curtailed)
if (accRows.length >= MINRUNS * 12) {
  const ratio = qn(accRows.map(r => 100 * r.pv_w / r.fc_w), 0.5);
  let status = 'ok', advice = 'The forecast fits well. No change needed.';
  if (ratio < 85) { status = 'info'; advice = 'The forecast is on the optimistic side here. Keep deciding on the cautious estimate (estimate10); the threshold advice above is already based on it.'; }
  else if (ratio > 115) { status = 'info'; advice = 'The forecast is on the pessimistic side here. The threshold advice above already takes this into account.'; }
  items.push({ key: 'forecast', title: 'How good is the forecast?', status: status,
    measured: 'Actual solar power was on average ' + Math.round(ratio) + '% of the forecast (' + Math.round(accRows.length / 4) + ' hours of daylight measured).', advice: advice });
} else {
  items.push({ key: 'forecast', title: 'How good is the forecast?', status: 'waiting',
    measured: Math.round(accRows.length / 4) + ' of ' + Math.round(MINRUNS * 3) + ' hours of daylight measured.', advice: 'No advice yet.' });
}

// 5. weather station (only when switched on)
if (useIrr) {
  const li = lasting.filter(r => typeof r.start_ctx.irr === 'number');
  if (li.length >= MINRUNS) {
    const i = Math.round(qn(li.map(r => r.start_ctx.irr), 0.25) / 10) * 10;
    const same = Math.abs(i - cur.irrStart) < 30;
    items.push({ key: 'irr', title: 'Weather station thresholds', status: same ? 'ok' : 'advice',
      measured: 'Most lasting solar sessions started with ' + i + ' W/m² or more.',
      advice: same ? 'Keep ' + cur.irrStart + ' W/m².' : 'Set irradiance to start to ' + i + ' W/m² and to hold to ' + Math.round(i * 0.75 / 10) * 10 + ' W/m² (now ' + cur.irrStart + ' / ' + cur.irrHold + ').',
      value: { irr_start: i, irr_hold: Math.round(i * 0.75 / 10) * 10 } });
  } else items.push({ key: 'irr', title: 'Weather station thresholds', status: 'waiting', measured: li.length + ' of ' + MINRUNS + ' solar sessions with irradiance collected.', advice: 'No advice yet.' });
}

// ---- change tracking: the advice follows the season, so note when it moves ----
const prev = flow.get('hescAdvicePrev') || {};
const pNow = (items.find(x => x.key === 'p_start' && x.value) || {}).value;
