    startStop: txt('input_text.hesc_charger_start_stop_entity'),
    solarBack: txt('input_text.hesc_charger_resume_entity'),
    modeEnt: txt('input_text.hesc_charger_mode_entity'),
    ecoVals: list(txt('input_text.hesc_charger_eco_value') || 'eco_mode').map(low),
    evConn: txt('input_text.hesc_ev_connected_sensor'),
    offVals: list(txt('input_text.hesc_ev_disconnected_values') || 'off,disconnected,ready,available,unplugged').map(low),
    evSoc: txt('input_text.hesc_ev_soc_sensor'),
