    else if (!canAct) why = 'Not set up: start/stop switch and back-to-solar entity needed';
    else if (homeNeed === null || C.kwh <= 0) why = 'Not set up: home battery size and level sensors needed';
    else if (!evConn) why = 'No EV connected';
    else if (planOwns || parkBusy) why = 'Charge plan has the charger';
    else if (releaseBusy) why = 'HPVC release running';
    else if (!sunUp) why = 'Sun down';
    else if (evCharging) {
        // rule 2: EV charges on sun; give the rest of the day back to the home batteries when only just enough
        const planNeeds = planGoal !== null && soc !== null && soc < planGoal - MARGIN;
        const tight = homeNeed > 0.5 && sunKwh <= 1.2 * homeNeed;
        if (common && ecoMode && tight && !planNeeds && K.evSince && now - K.evSince >= 10 * 60000 && room) {
            if (C.shadow) { hist({ event: 'home_first_would', reason: 'shadow mode' }); K.lastAt = now; }
            else {
                sw('off'); K.back = { t0: now, done: false }; K.count++; K.lastAt = now; K.homeFirst = true;
                hist({ event: 'home_first', reason: 'sun left today (' + sunKwh.toFixed(1) + ' kWh) only just enough for the home batteries (' + homeNeed.toFixed(1) + ' kWh)' });
            }
            why = 'Home batteries first: EV paused';
        } else why = 'EV charging · sun left ' + sunKwh.toFixed(1) + ' kWh, home batteries need ' + homeNeed.toFixed(1) + ' kWh' + (planNeeds ? ' (plan needs the EV charge)' : '');
    }
    else if (!ecoMode) why = 'Charger not in solar mode';
    else if (!evNeeds) why = 'EV full (' + Math.round(soc) + '%)';
    else if (K.homeFirst) why = 'Home batteries first for the rest of today';
    else if (spare < C.minEv) why = 'Sun left today for the home batteries (' + sunKwh.toFixed(1) + ' kWh left, ' + homeNeed.toFixed(1) + ' kWh needed)';
    else if (fcCaut === null || fcCaut < C.pStart) why = 'Waiting: forecast now ' + (fcCaut === null ? '-' : Math.round(fcCaut)) + ' W, start at ' + C.pStart + ' W';
    else if (!K.chgSince) why = 'Waiting: home batteries not taking the sun';
    else if (now - K.chgSince < C.tStable) why = 'Waiting: home batteries charging, check again in ' + Math.ceil((C.tStable - (now - K.chgSince)) / 60000) + ' min';
    else if (K.count >= C.maxDay) why = 'Done for today (' + K.count + ' of ' + C.maxDay + ')';
    else if (!room) why = 'Waiting until ' + hhmm(K.lastAt + C.gap) + ' (30 min between kickstarts)';
    else if (common) {
        if (C.shadow) { hist({ event: 'kick_would', reason: 'shadow mode' }); K.lastAt = now; why = '[shadow] would kickstart now'; }
        else {
            sw('on'); K.seq = { phase: 'start', t0: now, retried: false }; K.count++; K.lastAt = now;
            hist({ event: 'kick_start', reason: 'home batteries take ' + Math.round(homeW) + ' W, sun left ' + sunKwh.toFixed(1) + ' kWh, home batteries need ' + homeNeed.toFixed(1) + ' kWh', attempt: K.count });
            why = 'Kickstart: charger started';
        }
    } else why = 'Waiting';
}

const stateTxt = (C.shadow && C.on ? '[shadow] ' : '') + why + (C.on && K.count ? ' · today ' + K.count + ' of ' + C.maxDay : '');
if (K.last.status !== stateTxt && S['input_text.hesc_kick_status']) { K.last.status = stateTxt; msgs1.push(act('input_text.set_value', 'input_text.hesc_kick_status', { value: stateTxt.slice(0, 255) })); }
flow.set('hescKick', K);
node.status({ fill: K.seq || K.back ? 'yellow' : (C.on ? 'green' : 'grey'), shape: 'dot', text: stateTxt.slice(0, 60) });
return [msgs1, msgs2, msgs3];
